// Java Lambda handler — AWS_PROXY (Lambda Proxy) integration
public class OrderHandler
    implements RequestHandler<APIGatewayProxyRequestEvent, APIGatewayProxyResponseEvent> {

  @Override
  public APIGatewayProxyResponseEvent handleRequest(
      APIGatewayProxyRequestEvent event, Context ctx) {

    String orderId = event.getPathParameters().get("id");
    Map<String,String> qs = event.getQueryStringParameters();
    String body = event.getBody();        // client JSON as string

    // ... business logic ...

    return new APIGatewayProxyResponseEvent()
        .withStatusCode(200)
        .withHeaders(Map.of(
            "Content-Type", "application/json",
            "Access-Control-Allow-Origin", "*"))
        .withBody("{\"orderId\":\"" + orderId + "\",\"status\":\"SHIPPED\"}");
  }
}

